const imSleepZ = () => `<g id="zz">${[0, 1, 2].map((i) => `<text class="z" x="${980 + i * 60}" y="${440 - i * 70}" font-family="Anton" font-size="${70 + i * 20}" fill="#fbf7ef">Z</text>`).join('')}</g>`;


// ---------------------------------------------------------------- gravity helpers
const gvHud = (day: string, g: string) => imHud(day, `GRAVIDADE ${g}`, '#3a7aff');
// jump: a character bounces up by h px over a period (repeat), as in low gravity (slow, floaty arcs)
const gvBounce = (tl: gsap.core.Timeline, sel: string, t0: number, t1: number, h: number, per = 1.6) => tl.fromTo(`${sel} .mv`, { y: 0 }, { y: -h, duration: per / 2, yoyo: true, repeat: Math.max(1, Math.floor((t1 - t0) / (per / 2)) - 1), ease: 'sine.out' }, t0);
const gvBasket = (id: string, x: number, y: number, r = 34) => `<g id="${id}"><circle cx="${x}" cy="${y}" r="${r}" fill="#e86a20" ${bzO()}/><path d="M${x - r} ${y} H ${x + r} M${x} ${y - r} V ${y + r} M${x - r * 0.7} ${y - r * 0.7} Q ${x} ${y} ${x - r * 0.7} ${y + r * 0.7} M${x + r * 0.7} ${y - r * 0.7} Q ${x} ${y} ${x + r * 0.7} ${y + r * 0.7}" stroke="${BZ.ink}" stroke-width="4" fill="none"/></g>`;
const gvFridge = (x: number, y: number) => `<g transform="translate(${x} ${y})"><rect x="-90" y="-360" width="180" height="360" rx="16" fill="#e8f0f4" ${bzO()}/><path d="M-90 -220 h180" stroke="${BZ.ink}" stroke-width="6"/><rect x="58" y="-320" width="10" height="70" fill="${BZ.ink}"/></g>`;
