const gvCylinders = () => `<g>${[...Array(7)].map((_, i) => `<g class="cy"><g transform="translate(${360 + i * 200} 900)"><rect x="-50" y="-420" width="100" height="420" rx="40" fill="#3aa05a" ${bzO()}/><rect x="-20" y="-470" width="40" height="60" fill="#8a8f9e" ${bzO('stroke-width="5"')}/><text x="0" y="-200" text-anchor="middle" font-family="Anton" font-size="48" fill="#fff" transform="rotate(-90 0 -200)">O₂</text></g></g>`).join('')}</g>`;
